package dev.pathland.quarkus;

import dev.pathland.view.core.View;

import dev.pathland.observability.MicrometerTelemetry;
import dev.pathland.observability.TracingTelemetry;
import dev.pathland.server.MountedApp;
import dev.pathland.server.PathlandApp;
import dev.pathland.server.PathlandHost;
import dev.pathland.server.PathlandTelemetry;
import dev.pathland.server.StateStores;
import dev.pathland.view.core.state.InMemoryStateStore;
import io.micrometer.core.instrument.MeterRegistry;
import io.opentelemetry.api.trace.Tracer;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Disposes;
import jakarta.enterprise.inject.Instance;
import jakarta.enterprise.inject.Produces;
import jakarta.inject.Inject;
import jakarta.inject.Singleton;
import org.eclipse.microprofile.config.inject.ConfigProperty;

import java.util.ArrayList;
import java.util.List;

/**
 * CDI wiring for Pathland: builds the {@link PathlandHost} from the app's
 * {@link PathlandApp} bean (mounted at {@code "/"}) and any {@link MountedApp} beans
 * (each at its own subpath), and shuts it down with the application. The app provides
 * the root view:
 *
 * <pre>{@code
 * @ApplicationScoped
 * public class MyApp implements PathlandApp {
 *     public View newRoot() { return new MyHomeView(); }
 * }
 * }</pre>
 *
 * <p>Multiple apps share the server the same way (each at its own mount, with its own
 * framework base, WebSocket endpoint, and state scope):
 *
 * <pre>{@code
 * @Produces @Singleton
 * MountedApp support() { return MountedApp.of("/support", new SupportApp()); }
 * }</pre>
 *
 * <p>SSR debug comments are opt-in via the {@code pathland.debug-html} config property
 * (default {@code false}); when enabled every rendered node is prefixed with an HTML
 * comment naming its component type and the modifiers applied.
 */
@ApplicationScoped
public class PathlandRegistryProducer {

    @Inject
    Instance<PathlandApp> apps;

    @Inject
    Instance<MountedApp> mounts;

    @Inject
    MeterRegistry meterRegistry;

    /** Present only when the app adds {@code quarkus-opentelemetry} (opt-in tracing). */
    @Inject
    Instance<Tracer> tracer;

    /** Tracing is opt-in: never touch the OTel API when the extension is disabled. */
    @Inject
    @ConfigProperty(name = "quarkus.otel.enabled", defaultValue = "true")
    boolean otelEnabled;

    @Inject
    @ConfigProperty(name = "pathland.debug-html", defaultValue = "false")
    boolean debugHtml;

    /** Opt the DOM client into the per-window-id service worker (issue #155); default off. */
    @ConfigProperty(name = "pathland.service-worker", defaultValue = "false")
    boolean serviceWorker;

    /**
     * The observability seam: a Micrometer adapter over the app's {@link MeterRegistry}
     * (always present via {@code quarkus-micrometer}), decorated with OpenTelemetry spans
     * when a {@link Tracer} is available and tracing is enabled.
     */
    @Produces
    @Singleton
    PathlandTelemetry telemetry() {
        PathlandTelemetry telemetry = new MicrometerTelemetry(meterRegistry);
        if (otelEnabled && tracer.isResolvable()) {
            telemetry = new TracingTelemetry(telemetry, tracer.get());
        }
        return telemetry;
    }

    @Produces
    @Singleton
    PathlandHost host(PathlandTelemetry telemetry) {
        List<MountedApp> list = new ArrayList<>();
        mounts.forEach(list::add);
        PathlandApp lone = apps.stream().findFirst().orElse(null);
        if (lone != null && list.stream().noneMatch(m -> "/".equals(m.path()))) {
            list.add(0, MountedApp.of("/", lone));
        }
        return new PathlandHost(
                list, StateStores.redisOrFallback(new InMemoryStateStore()), debugHtml, telemetry, serviceWorker);
    }

    void shutdown(@Disposes PathlandHost host) {
        host.shutdown();
    }
}

    @TestHTTPResource("/")
    lateinit var base: URL

    @Test
    fun ssrRendersTheKotlinDemo() {
        val response = get("/")

        assertEquals(200, response.statusCode())
        assertTrue(response.body().contains("Library"), response.body())
        assertTrue(response.body().contains("Building on Solid Ground"), response.body())
        assertTrue(response.body().contains("8 songs · 8 albums"), response.body())
        assertTrue(response.body().contains("Pathland · Building on Solid Ground"), response.body())
    }

    @Test
    fun adViewIsMountedAndEmbeddedThroughTheProxy() {
        val html = get("/").body()

        assertTrue(html.contains("Pathland Ads"), "the proxied ad app's title is embedded: $html")
        assertTrue(html.contains("Clicked 0 times"), "the ad app's counter renders through the proxy")
        assertTrue(html.contains("data-pathland-id=\"1073741825\""),
            "the ad subtree carries remapped ids from the proxy range")

        val ad = get("/ad")
        assertEquals(200, ad.statusCode(), "the ad app is mounted at /ad")
        assertTrue(ad.body().contains("Pathland Ads"), "the ad app renders directly at /ad")
    }

    @Test
    fun ssrServesTheContentHashedDomBundle() {
        val html = get("/").body()
        assertFalse(html.contains("/_pathland/dom-renderer.js\""),
                "the pre-hash fallback must not be emitted when the app manifest is visible")

        val src = Regex("""src="(/_pathland/dom-renderer-[^"]+\.js)"""")
            .find(html)?.groupValues?.get(1)
        assertNotNull(src, "the SSR document references the content-hashed DOM bundle: $html")

        val bundle = get(src!!)
        assertEquals(200, bundle.statusCode(), "GET $src")
        assertTrue(bundle.headers().firstValue("Content-Type").orElse("")
                .startsWith("text/javascript"), "served as JavaScript")
    }

    private fun get(path: String): HttpResponse<String> =
        HttpClient.newHttpClient().send(
            HttpRequest.newBuilder(URI.create(base.toString()).resolve(path)).GET().build(),
            HttpResponse.BodyHandlers.ofString(),
        )
